Implement the Verilog module based on the following description.
Build a 6-bit binary counter with synchronous active low reset signal and a load enable signal. When load is high, load the counter with the provided value.
// (1) reset_n: Resets the counter to 6'b000000 when low.
// (2) load: Enables the load operation when high.
// (3) load_val: The value to be loaded into the counter when load is high.
// (4) q: The value of the counter.

module top_module(
    input clk,
    input reset_n,
    input load,
    input [5:0] load_val,
    output reg [5:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    input load,
    input [5:0] load_val,
    output reg [5:0] q
);

    always @(posedge clk) begin
        if (!reset_n) begin
            // Synchronous reset: Reset the counter to 6'b000000
            q <= 6'b000000;
        end else if (load) begin
            // Load operation: Load the counter with the provided value
            q <= load_val;
        end else begin
            // Binary counter: Increment by 1
            q <= q + 1;
        end
    end

endmodule

