module top_module(
  input clk,
  input reset,
  input enable,
  output reg [3:0] counter_out,
  output reg latch_out
);reg [3:0] counter_reg;
  reg d_latch_reg;

  always @(posedge clk) begin
    if (reset) begin
      counter_reg <= 4'b0000;
      d_latch_reg <= 1'b0;
    end else begin
      counter_reg <= counter_reg + 1;
      d_latch_reg <= enable ? counter_reg[3] : d_latch_reg;
    end
  end

  assign counter_out = counter_reg;
  assign latch_out = d_latch_reg;

endmodule

