description:
Design a clock divider that reduces the frequency of an input clock signal. This module takes in a clock signal and an active-low reset signal. It counts clock cycles using a 20-bit register and toggles the output clock signal, clk_div, every 1,048,576 clock cycles (2^20). The output clk_div will be half the frequency of the input clk after the reset condition is deactivated, providing a lower frequency clock signal suitable for driving other circuit components with different timing requirements.
module top_module(
			clk,rst_n,
			clk_div	
		);

code:
module top_module(
			clk,rst_n,
			clk_div	
		);input clk;		
input rst_n;	

output clk_div;	


reg[19:0] cnt;	

always @ (posedge clk or negedge rst_n)	
	if(!rst_n) cnt <= 20'd0;
	else cnt <= cnt+1'b1;	


reg clk_div_r;	

always @ (posedge clk or negedge rst_n) 
	if(!rst_n) clk_div_r <= 1'b0;
	else if(cnt == 20'hfffff) clk_div_r <= ~clk_div_r;	

assign clk_div = clk_div_r;	

endmodule

