module top_module(rclk, rrst, rce, oe, raddr, dout,wclk, wrst, wce, we, waddr, di);parameter aw = 5; 
  parameter dw = 16; 
  input rclk; 
  input rrst; 
  input rce; 
  input oe; 
  input [aw-1:0] raddr; 
  output [dw-1:0] dout; 
  input wclk; 
  input wrst; 
  input wce; 
  input we; 
  input [aw-1:0] waddr; 
  input [dw-1:0] di; 
  reg [dw-1:0] mem [(1<<aw) -1:0] ; 
  reg [aw-1:0] ra; 
  always @(posedge rclk) 
  if (rce) 
  ra <= #1 raddr; 
  assign dout = mem[ra]; 
  always @(posedge wclk) 
  if (we && wce) 
  mem[waddr] <= #1 di; 
 endmodule

