module top_module(
  input clk,
  input [7:0] pattern,
  input [254:0] data,
  output reg detect
);reg [7:0] shift_reg [31:0];
  reg [7:0] shifted_data [31:0];
  reg [7:0] sum [15:0];
  reg [3:0] index;

  always @(posedge clk) begin
    // Shift the data into the shift register
    for (index = 31; index > 0; index = index - 1) begin
      shift_reg[index] <= shift_reg[index - 1];
    end
    shift_reg[0] <= data[7:0];

    // Shift the shifted data into the binary tree adder
    for (index = 31; index > 0; index = index - 1) begin
      shifted_data[index] <= shifted_data[index - 1];
    end
    shifted_data[0] <= shift_reg[31];

    // Calculate the sum using the binary tree adder
    sum[0] <= shifted_data[0] + pattern;
    sum[1] <= shifted_data[1] + sum[0];
    sum[2] <= shifted_data[2] + sum[1];
    sum[3] <= shifted_data[3] + sum[2];
    sum[4] <= shifted_data[4] + sum[3];
    sum[5] <= shifted_data[5] + sum[4];
    sum[6] <= shifted_data[6] + sum[5];
    sum[7] <= shifted_data[7] + sum[6];
    sum[8] <= shifted_data[8] + sum[7];
    sum[9] <= shifted_data[9] + sum[8];
    sum[10] <= shifted_data[10] + sum[9];
    sum[11] <= shifted_data[11] + sum[10];
    sum[12] <= shifted_data[12] + sum[11];
    sum[13] <= shifted_data[13] + sum[12];
    sum[14] <= shifted_data[14] + sum[13];
    sum[15] <= shifted_data[15] + sum[14];

    // Check if the sum matches the target pattern
    if (sum[15] == 8'b00000000) begin
      detect <= 1;
    end else begin
      detect <= 0;
    end
  end

endmodule

