  input reset,
  input [2:0] sel,
  input [3:0] data,
  output reg [3:0] Q
);reg [3:0] shift_reg;
  wire xor_out;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 4'b0000;
    end else begin
      shift_reg <= {shift_reg[2:0], xor_out};
    end
