module sequence_detector (
	input clk,
	input resetn,
	input seq_in,
	output seq_detected);

	parameter IDLE=0, S1=1, S11=2, S110=3, DETECT=4;
	reg [2:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			IDLE: next_state = seq_in ? S1 : IDLE;
			S1: next_state = seq_in ? S11 : IDLE;
			S11: next_state = seq_in ? S11 : S110;
			S110: next_state = seq_in ? DETECT : IDLE;
			DETECT: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	assign seq_detected = (state == DETECT);
endmodule

